effect.shader:

    vec4 newLayer( vec4 a, vec4 b) {
    return a * (1. - b.a) + b;
    }

    mat2 rot2m(float a){

	float s = sin(a);
	float c = cos(a);

	return mat2(c, -s, s, c);
    }

    vec2 l2s( vec2 v ) {
        return (vec4(v,0.,1.)*acLayerToScreen).xy;
    }

   #define fragCoord gl_FragCoord.xy

   /////////////////////////

    // #define time (PROGGRES / 2.0)

    #define PI2 6.28
    #define PI 3.1416


    // Point to polar coord
    vec2 p_to_pc(vec2 p){
        return vec2(atan(p.y, p.x), length(p));
    }

    // Polar coord to point
    vec2 pc_to_p(vec2 pc){
        return vec2(pc.y * cos(pc.x), pc.y * sin(pc.x));
    }

    // I use these fields to create and tweak the snowflakes
    vec2 fieldA(vec2 pc){
        // Modify angle and distance
        pc.y += 0.02 * floor(cos(pc.x * 6.0 ) * 5.0);
        pc.y += 0.01 * floor(10.0 * cos(pc.x * 30.0));
        pc.y += 0.5 * cos(pc.y * 10.0);

        // Take back to position
        return pc;
    }


    // Different values of f happen to give quite different
    // snowflake shapes. Interesting...
    vec2 fieldB(vec2 pc, float f){
        // Modify angle and distance
        pc.y += 0.1 * cos(pc.y * 100.0 + 10.0);
        pc.y += 0.1 * cos(pc.y * 20.0 + f);
        pc.y += 0.04 * cos(pc.y * 10.0 + 10.0);

        return pc;
    } 

    vec4 snow_flake(vec2 p, float f){

        vec4 col = vec4(0.0);

      vec2 pc = p_to_pc(p * 10.0  * (8.-(4.+DEPTH)));


        pc = fieldA(fieldB(pc, f));

        p = pc_to_p(pc);

        float d = length(p);

        if(d < 0.3){
            col.rgba += vec4(1.0);
        }

        return col;
    }

    vec4 snow(vec2 p){

        vec4 col = vec4(0.0);

        p.y += autop? 2.0 * ((EVO/2.0)+(acTime*0.5)) * 0.8 : 2.0 * (EVO/2.0) * 0.8;

        p = fract(p + 0.5) - 0.5;

        p *= 1.0;


        p.x += autop? 0.01 * cos(p.y * 3.0 + p.x * 3.0 + ((EVO/2.0)+(acTime*0.5)) * PI2) :
              0.01 * cos(p.y * 3.0 + p.x * 3.0 + (EVO/2.0) * PI2);


        // Just me pseudo randomly adding snowflakes
        // Could be optimized by not calling the function 8 times
        // (using some field distortion )
        if(LAYERS >= 1.0){
          col += snow_flake(p, 1.0);
        }
        if(LAYERS >= 2.0){
            col += snow_flake(p + vec2(0.2, -0.1), 24.0);
        }
        if(LAYERS >= 3.0){
            col += snow_flake(p * 2.0 + vec2(-0.4, -0.5), 5.0);
        }
        if(LAYERS >= 4.0){
            col += snow_flake(p * 1.0 + vec2(-0.2, 0.4), 9.0);
        }
        if(LAYERS >= 5.0){
          col += 2.0 * snow_flake(p * 1.0 + vec2(0.4, -0.4), 5.0);
        }
        if(LAYERS >= 6.0){
          col += snow_flake(p * 1.0 + vec2(-1.2, 1.2), 9.0);
        }
        if(LAYERS >= 7.0){
          col += snow_flake(p * 1.0 + vec2(2.4, -1.2), 5.0);
        }
        if(LAYERS >= 8.0){
          col += snow_flake(p * 1.0 + vec2(-1.2, 1.1), 9.0);
        }

        return col * vec4( color1.rgb,0.0);
    }

   /////////////////////////
    void main ()
    {

        vec4 texColor = texture2DCv(inputImg.texture,acScreenNorm);
        vec4 texColorX = vec4(0.0,0.0,0.0,1.0) * texColor.a;
        vec2 image_size = getTexSize(inputImg.size);
        float maxF = max(acScreenSize.x, acScreenSize.y);
        vec2 texelSize = 1.0 / vec2(maxF, maxF);

        vec2 TanRyu;
        TanRyu = ((vec2(acScreenNorm.x,1.0-acScreenNorm.y)*acScreenSize)-acLayerCenter)/acLayerSize;
        TanRyu.y*=acLayerSize.y/acLayerSize.x;

        TanRyu /= scale;
        TanRyu *= rot2m((-180.0+angle)*0.0174533);
        TanRyu += vec2((0.0+position.x), (0.0+position.y))*vec2(-1.,1.)/500.;

        vec2 scaleVec;
        scaleVec = vec2(scale*stretch.x,scale*stretch.y);
        TanRyu /= scaleVec;

        /////////////////////////

    	vec4 fragColor;

        vec2 uv = TanRyu;
        float x = uv.x;
        float y = uv.y;

        vec2 p = vec2(x, y);

        vec4 col = vec4(0.0);

        col += snow(p * 2.0);
        col += 0.8 * snow(p * 4.0);

        col.a = 0.0;

        fragColor = DEPTH < 0.001 ? vec4(0.0) : col;

    	vec4 factor = mix(texColorX,fragColor, 1.0);

        vec4 resultfinal;
        if( blendMode==0 ) {                // normal
            // resultfinal = (factor * bright) * texColor.a;
            resultfinal = (newLayer(texColor, factor) * bright) * texColor.a;
        } else if( blendMode==1 ) {         // multiply
            factor *= bright;
            vec4 c = factor + vec4(1.)*(1.-factor.a);
            resultfinal = vec4((texColor.rgb/texColor.a)*c.rgb,1.0) * texColor.a;
        } else if( blendMode==2 ) {         // screen
            factor *= bright;
            resultfinal = vec4( 1.-((1.-(texColor.rgb/texColor.a))*(1.-factor.rgb)),1.0) * texColor.a;
        }

    	gl_FragColor = mix(texColor, resultfinal, alpha);
    	// }
    }
